def variable(symbol: str, name: str, unit: str, definition: str, role: str, status: str = "explicit-defined") -> dict:
    return {"symbol": symbol, "normalized_name": name, "unit": unit, "definition": definition, "role": role, "source_status": status}


def equation(index: int, page: int, label: str, source_expression: str, normalized_latex: str, symbols: list[str], purpose: str, confidence: str = "high") -> dict:
    return {
        "equation_id": f"EQ-{TYPE}-{YEAR}-{SHORT}-{index:03d}",
        "page": page,
        "label": label,
        "source_expression": source_expression,
        "normalized_latex": normalized_latex,
        "purpose": purpose,
        "variable_symbols": symbols,
        "source_type": "paper",
        "visual_checked": True,
        "transcription_confidence": confidence,
    }


def condition(status: str, *details: str) -> dict:
    return {"status": status, "details": list(details)}


def model(
    index: int,
    page: int,
    section: str,
    family: str,
    purpose: str,
    variables: list[dict],
    inputs: list[str],
    outputs: list[str],
    equations: list[dict],
    assumptions: list[str],
    algorithm_steps: list[str],
    validation_refs: list[str],
    limitations: list[str],
    missing_details: list[str],
    *,
    origin: str = "paper-specific",
    parameter_method: str = "The paper selects route, aircraft, radar, search, and condition values from cited context or a single worked scenario; it does not estimate a calibrated incident model.",
    feasibility: str = "partial",
    feasibility_analysis: str = "The source gives a finite density-to-grid-to-path workflow and one worked example, but no executable archive, field calibration, independent holdout, or operational trial.",
    convergence: str = "Finite cell loops and a 60-iteration path cap terminate the supplied code; no grid, time-step, parameter, tie-rule, or optimization convergence study is reported.",
    cost: str = "Cost scales with POC integrals, cell count, coordinate transforms, repeated POC updates, neighborhood comparisons, search assets, and path iterations; runtime and hardware are not reported.",
) -> dict:
    parameters = [item["symbol"] for item in variables if item["role"] == "parameter"]
    return {
        "model_id": f"MU-{TYPE}-{YEAR}-{SHORT}-{index:03d}",
        "page": page,
        "section": section,
        "family": family,
        "purpose": purpose,
        "base_or_modification": origin,
        "summary": purpose,
        "variables": variables,
        "inputs": inputs,
        "outputs": outputs,
        "governing_equations": equations,
        "equation_status": {
            "status": "present" if equations else "omitted-by-paper",
            "reason": "All displayed equations assigned to this component were reconciled against bounded page and focused formula proxies." if equations else "The source supplies this layer in prose, plots, code, matrices, or a decision narrative without a separate displayed mathematical equation.",
        },
        "objectives": [purpose, "Produce a traceable containment, coordinate, detection, update, path, sensitivity, example, or decision output without treating the worked example as field validation."],
        "constraints": [
            "Retain the source's coordinate system, support, units, cell layout, detector geometry, fleet assumptions, update semantics, and path-selection rule at each interface.",
            "Preserve printed algebra, support, notation, and code defects as source evidence; any corrected implementation must be labeled as a separate extension.",
        ],
        "conditions": {
            "initial": condition("present", "Last-contact state, route endpoints, aircraft/search parameters, distribution support, and POC matrix must be initialized before the component runs."),
            "boundary": condition("present", "The component is bounded by a linear transoceanic IFP, open water, three-sigma deviation, stationary debris, persistent detectability, constant speeds, and homogeneous search assets."),
            "equilibrium": condition("not-applicable", "The paper uses finite transformations, regional integration, repeated updates, and greedy path steps rather than an equilibrium solve."),
        },
        "parameter_estimation": {"status": "partial", "method": parameter_method, "parameters": parameters},
        "algorithm": {"status": "partial", "steps": algorithm_steps, "software": ["The paper supplies Mathematica fragments and Excel tables but no frozen notebook/workbook, version, complete input file, run log, or executable environment."], "convergence_criteria": convergence},
        "assumptions": assumptions,
        "identifiability_feasibility": {"status": feasibility, "analysis": feasibility_analysis},
        "handoff_outputs": outputs,
        "validation_refs": validation_refs,
        "computational_cost": cost,
        "strengths": ["The component occupies a source-ordered position in the last-contact -> containment -> cell -> coordinates -> detection -> update -> path -> decision chain.", "Its variables, equations, code or outputs remain distinguishable from later warnings and independent repairs."],
        "limitations": limitations,
        "missing_details": missing_details,
    }


