def validate(record: dict) -> None:
    equations = [item for model_unit in record["models"] for item in model_unit["governing_equations"]]
    if len(record["models"]) != 11:
        raise ValueError(f"expected 11 models, found {len(record['models'])}")
    if len(equations) != 37:
        raise ValueError(f"expected 37 equations, found {len(equations)}")
    source_group_order = list(range(1, 29)) + [37, 29, 30] + list(range(31, 37))
    if [item["equation_id"] for item in equations] != [f"EQ-B-2015-39173-{index:03d}" for index in source_group_order]:
        raise ValueError("equation records must retain the declared source-group order")
    if len(record["dependency_edges"]) != 15:
        raise ValueError("expected 15 typed model dependency edges")


def main() -> None:
    if STAGE.exists():
        raise SystemExit(f"refusing to overwrite existing stage: {STAGE}")
    record = build_models()
    validate(record)
    STAGE.mkdir(parents=True)
    target = STAGE / "models.json"
    target.write_text(json.dumps(record, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(json.dumps({"paper_id": PAPER_ID, "models": len(record["models"]), "equations": 37, "dependency_edges": len(record["dependency_edges"]), "stage": str(target), "status": "pass"}, sort_keys=True))


if __name__ == "__main__":
    main()
